def _should_promote_legacy_internal_calendar_color(color: str | None) -> bool:
    if not color:
        return False

    if color.lower() == LEGACY_INTERNAL_CALENDAR_DEFAULT_COLOR.lower():
        return False

    return bool(re.fullmatch(HEX_COLOR_PATTERN, color))


