class ExternalCalendarAccountCreateSerializer(
    UniformTemplateSerializerMixin, serializers.ModelSerializer[ExternalCalendarAccount]
):
    """Serializer for creating an ExternalCalendarAccount"""

    access_token = serializers.CharField(
        required=False, allow_blank=True, write_only=True
    )
    refresh_token = serializers.CharField(
        required=False, allow_blank=True, write_only=True
    )
    visibility_settings = CalendarVisibilitySerializer(required=False)
    associated_user_ids = serializers.ListField(
        child=serializers.IntegerField(), required=False, write_only=True
    )
    associated_child_ids = serializers.ListField(
        child=serializers.IntegerField(), required=False, write_only=True
    )

    class Meta:
        model = ExternalCalendarAccount
        fields = [
            "provider",
            "account_name",
            "display_color_override",
            "calendar_id",
            "access_token",
            "refresh_token",
            "token_expiry",
            "ical_url",
            "is_active",
            "sync_enabled",
            "visibility_settings",
            "associated_user_ids",
            "associated_child_ids",
            "type",
            "sports_subcategory",
            "uniform_template",
        ]

    def create(self, validated_data: dict[str, Any]) -> ExternalCalendarAccount:
        from users.models import Child

        visibility_data = None
        associated_user_ids: list[int] = []
        associated_child_ids: list[int] = []

        if "visibility_settings" in validated_data:
            visibility_data = validated_data.pop("visibility_settings")

        if "associated_user_ids" in validated_data:
            associated_user_ids = validated_data.pop("associated_user_ids")

        if "associated_child_ids" in validated_data:
            associated_child_ids = validated_data.pop("associated_child_ids")

        calendar = ExternalCalendarAccount.objects.create(**validated_data)

        # Add associated users
        if associated_user_ids:
            users = User.objects.filter(id__in=associated_user_ids)
