                    messages.error(request, "Please provide a valid calendar URL.")
                    return redirect("calendars:quick_connect")

                safe_url = normalize_and_validate_ics_url(url)
                if safe_url is None:
                    messages.error(
                        request,
                        "Calendar URL points to a private or restricted host.",
                    )
                    return redirect("calendars:quick_connect")
                url = safe_url
                parsed_url = urlparse(url)

                # Auto-detect the provider from URL domain
                domain = parsed_url.netloc.lower()
                if "google.com" in domain or "googleapis.com" in domain:
                    detected_provider = "GOOGLE"
                elif (
                    "outlook" in domain
                    or "office365" in domain
                    or "microsoft.com" in domain
                ):
                    detected_provider = "OUTLOOK"
                elif "icloud.com" in domain or "apple.com" in domain:
                    detected_provider = "APPLE"
                else:
                    detected_provider = "OTHER"

                # If no name provided, try to fetch metadata for a better default
                if not calendar_name:
                    try:
                        metadata = fetch_ics_metadata(url, timeout=3)  # Quick timeout
                        if metadata:
                            # Use the first suggestion or calendar name from metadata
                            if metadata.get("suggested_names"):
                                calendar_name = metadata["suggested_names"][0]
                            elif metadata.get("calendar_name"):
                                calendar_name = metadata["calendar_name"]
                    except Exception as e:
                        logger.debug(
                            f"Could not fetch metadata for name suggestion: {e}"
                        )

                # Create the external calendar account
                # Generate deterministic provider_uid from normalized URL and user to prevent duplicates
                canonical = url.strip().lower()
                uid_source = f"{user.id}:{canonical}"
                stable_hash = uuid.uuid5(uuid.NAMESPACE_URL, uid_source)

                calendar = ExternalCalendarAccount.objects.create(
                    user=user,
                    provider=detected_provider,
                    provider_uid=f"url_{stable_hash}",  # Deterministic ID based on URL and user
                    account_email="",  # Leave empty since we don't have a real email for URL-based calendars
                    account_name=calendar_name or "Quick Calendar",
                    ical_url=url,  # Use normalized URL
                    type=calendar_type,
                    sports_subcategory=sports_subcategory,  # Already validated above
                    is_active=True,
                    sync_enabled=True,
                )

                messages.success(
                    request,
                    f"Calendar '{calendar.account_name}' connected successfully! "
                    "Events will sync shortly.",
                )

                # Trigger initial sync if available
                if sync_external_calendar:
                    sync_external_calendar.delay(calendar.id)
                else:
                    logger.warning(
                        f"Sync task not available for calendar {calendar.id}"
                    )

                return redirect("calendars:calendar_list")

            except Exception as e:
                logger.error(f"Error creating quick calendar connection: {str(e)}")
                messages.error(
                    request,
                    "Failed to connect calendar. Please check the URL and try again.",
                )
                return redirect("calendars:quick_connect")

        elif provider == "URL" and not calendar_url:
            messages.error(request, "Please provide a calendar URL.")
            return redirect("calendars:quick_connect")
        else:
            messages.error(
                request, "Invalid request. Please select a provider or provide a URL."
            )
            return redirect("calendars:quick_connect")

    # GET request - show the quick connect form
    context = {
        "title": "Add External Calendar",
        "description": "Connect calendars from Google, sports teams, schools, or any source with an iCal URL",
    }
    return render(request, "calendars/quick_connect.html", context)


