    with transaction.atomic():
        # Delete associated visibility rules first
        ExternalAccountVisibility.objects.filter(external_account=account).delete()
        # Delete sync logs, modified/deleted event records if necessary (similar to external_calendar_delete)
        SyncLog.objects.filter(calendar=account).delete()  # Assuming 'calendar' FK name
        ModifiedExternalEvent.objects.filter(calendar=account).delete()
        DeletedExternalEvent.objects.filter(calendar=account).delete()
        # Delete future events linked by string calendar_id (not a FK, no CASCADE).
        # Past events are kept as history.
        Event.secure.for_user(user).filter(
            is_external=True,
            calendar_id=str(account.id),
            external_source=account.provider,
            start_time__gte=timezone.now(),
        ).delete()
        # Delete the account itself
        account.delete()

