        from allauth.socialaccount.providers import registry
    except ImportError:
        logger.info(
            "django-allauth not installed; Google connect URL unavailable for external accounts"
        )
        return None

    try:
        return registry.by_id("google", request)
    except Exception as exc:  # pragma: no cover - defensive logging path
        logger.warning("Unable to load Google provider for external accounts: %s", exc)
        return None


def _get_google_connect_url(request: HttpRequest) -> str | None:
    """
    Build the connect URL for Google accounts using django-allauth.
    Returns None when the provider or integration isn't available.
    """
    provider = _get_google_provider(request)
    if not provider:
        return None

    try:
        url: str = provider.get_login_url(request, process="connect")
        return url
    except Exception as exc:  # pragma: no cover - defensive logging path
        logger.warning("Failed to build Google connect URL: %s", exc)
        return None


