def _compile_event_title_pattern(terms: tuple[str, ...]) -> re.Pattern:
    escaped_terms = [re.escape(term).replace(r"\ ", r"\s+") for term in terms]
    return re.compile(r"\b(?:" + "|".join(escaped_terms) + r")\b", re.IGNORECASE)


